suppressPackageStartupMessages({library(Matrix);library(ggplot2);library(irlba);library(uwot)})
out_dir <- file.path("data","Arthritis")
rna <- readRDS(file.path(out_dir,"Arthritis.rna.rds")); meta <- readRDS(file.path(out_dir,"Arthritis.meta.rds"))
lib <- Matrix::colSums(rna); norm <- rna %*% Diagonal(x=1e4/pmax(lib,1)); norm@x <- log1p(norm@x)
means <- Matrix::rowMeans(norm); vars <- Matrix::rowMeans(norm^2)-means^2; hv <- order(vars,decreasing=TRUE)[seq_len(min(2000,length(vars)))]
pca <- irlba::prcomp_irlba(t(norm[hv,,drop=FALSE]),n=20,center=TRUE,scale.=FALSE)
emb <- uwot::umap(pca$x,n_neighbors=30,min_dist=.3,metric="cosine",n_threads=8,verbose=FALSE)
emb <- as.data.frame(emb); colnames(emb)<-c("UMAP1","UMAP2"); emb$celltype <- meta$celltype; n_by_type<-table(emb$celltype); emb$label<-paste0(emb$celltype," (",n_by_type[emb$celltype],")")
p <- ggplot(emb,aes(UMAP1,UMAP2,colour=label))+geom_point(size=.22,alpha=.45)+theme_classic(base_size=11)+labs(title="Arthritis tissue (joint)",subtitle="Fast RNA PCA/UMAP exploration; GEO post-QC cells",colour=NULL)+guides(colour=guide_legend(override.aes=list(size=3,alpha=1)))
ggsave(file.path(out_dir,"Arthritis.celltype_umap.png"),p,width=6.5,height=5,dpi=220)
qc_metrics<-c("nCount_RNA","nFeature_RNA","nCount_ATAC","nFeature_ATAC"); qlong<-do.call(rbind,lapply(qc_metrics,function(nm)data.frame(celltype=meta$celltype,metric=nm,value=as.numeric(meta[[nm]]))))
q<-ggplot(qlong,aes(celltype,value,fill=celltype))+geom_violin(scale="width",trim=TRUE)+facet_wrap(~metric,scales="free_y",ncol=2)+theme_classic(base_size=10)+theme(axis.text.x=element_text(angle=35,hjust=1),legend.position="none")+labs(title="Arthritis data exploration: count distributions",x=NULL,y=NULL)
ggsave(file.path(out_dir,"Arthritis.qc_violin.png"),q,width=9,height=6,dpi=220)
saveRDS(list(pca=pca$x,umap=emb),file.path(out_dir,"Arthritis.exploration_embedding.rds"),compress="gzip")
cat("Wrote fast arthritis exploration for",nrow(emb),"cells.\n")
